// PRD 04 D14: every shipped procedural rig, audio file, look HDRI and menu portrait has a build-readable rights record
// (src/assets/rights-manifest.ts, generated by tools/gen-rights-manifest.mjs).
import { describe, expect, it } from "vitest";
import { AUDIO_MANIFEST } from "../../../src/audio-manifest.js";
import { MODEL_INFO, MODEL_KEYS } from "../../../src/aura-assets.js";
import { AUDIO_RIGHTS, ENVIRONMENT_RIGHTS, MODEL_RIGHTS, PORTRAIT_RIGHTS, PROCEDURAL_RIGHTS } from "../../../src/assets/rights-manifest.js";
import { LOOK_HDRI_FILES } from "../../../src/scenes/looks.js";
import { PORTRAITS } from "../../../src/ui/portraits.js";

describe("rights manifest", () => {
  it("ships zero external GLB model files", () => {
    expect(MODEL_RIGHTS).toEqual([]);
  });

  it("lists every procedural model as drawn from first-party scene geometry", () => {
    const procedural = MODEL_KEYS.filter((key) => MODEL_INFO[key].procedural);
    expect(procedural).toHaveLength(MODEL_KEYS.length);
    expect(PROCEDURAL_RIGHTS.map((record) => record.key).sort()).toEqual([...procedural].sort());
    for (const record of PROCEDURAL_RIGHTS) {
      expect(record.note, record.key).toMatch(/procedural/i);
      expect(record.license, record.key).toMatch(/AuraOne/);
    }
  });

  it("has a record for every recorded audio file, none of them free-tier", () => {
    for (const kind of ["lines", "songs", "beds", "sfx"] as const) {
      const recorded = Object.keys(AUDIO_MANIFEST[kind]).sort();
      expect(AUDIO_RIGHTS[kind].files.map((file) => file.id).sort(), kind).toEqual(recorded);
      expect(Object.keys(AUDIO_RIGHTS[kind].tiers), kind).not.toContain("free");
    }
  });

  it("has a CC0 record for each look HDRI", () => {
    expect(ENVIRONMENT_RIGHTS.map((record) => record.file).sort()).toEqual([...LOOK_HDRI_FILES].sort());
    for (const record of ENVIRONMENT_RIGHTS) expect(record.license).toMatch(/CC0/);
  });

  it("has a record for every menu portrait, backed by its procedural character rig and AuraOne licence", () => {
    expect(PORTRAIT_RIGHTS.map((record) => record.id).sort()).toEqual(Object.keys(PORTRAITS).sort());
    for (const record of PORTRAIT_RIGHTS) {
      const url = Object.entries(PORTRAITS).find(([id]) => id === record.id)?.[1];
      expect(url?.endsWith(`/${record.file.replace(/^src\//, "")}`), record.id).toBe(true);
      expect(PROCEDURAL_RIGHTS.some((r) => r.key === record.id), record.id).toBe(true);
      expect(record.license, record.id).toMatch(/AuraOne/);
      expect(record.sha256, record.id).toMatch(/^[0-9a-f]{64}$/);
    }
  });
});
